use super::*;

fn priority_item(id: &str, priority: EvidencePriority) -> EvidenceItem {
    EvidenceItem::new(
        id,
        "src/x.rs:1",
        "equal length evidence",
        priority,
        EvidenceState::Verified,
    )
}

#[test]
fn elevated_serializes_as_snake_case() {
    let encoded = blazingly_json::to_string(&EvidencePriority::Elevated).unwrap();
    assert_eq!(encoded, "\"elevated\"");
    assert_eq!(
        blazingly_json::from_str::<EvidencePriority>(&encoded).unwrap(),
        EvidencePriority::Elevated
    );
}

#[test]
fn high_then_elevated_then_normal_under_tight_budgets() {
    let items = vec![
        priority_item("normal__", EvidencePriority::Normal),
        priority_item("elevated", EvidencePriority::Elevated),
        priority_item("high____", EvidencePriority::High),
    ];
    let one_item_tokens = compile_context_with(
        &ContextRequest {
            items: vec![items[0].clone()],
            max_tokens: 1_000,
            deduplicate: false,
        },
        &CharDiv4Counter,
    )
    .unwrap()
    .selected_estimated_tokens;

    for (slots, included, omitted) in [
        (1, vec!["high____"], vec!["elevated", "normal__"]),
        (2, vec!["high____", "elevated"], vec!["normal__"]),
    ] {
        let packet = compile_context_with(
            &ContextRequest {
                items: items.clone(),
                max_tokens: one_item_tokens * slots,
                deduplicate: false,
            },
            &CharDiv4Counter,
        )
        .unwrap();
        assert_eq!(packet.included_ids, included);
        assert_eq!(packet.omitted_ids, omitted);
    }
}

