use super::*;

#[test]
fn elevated_sits_between_high_and_normal_under_a_tight_budget() {
    let normal = item("normal", &"n".repeat(80), EvidencePriority::Normal);
    let elevated = item("elevated", &"e".repeat(80), EvidencePriority::Elevated);
    let high = item("high", &"h".repeat(80), EvidencePriority::High);
    let cost = |item: &EvidenceItem| CharDiv4Counter.count(&render_item(item, &item.content));
    let request = ContextRequest {
        items: vec![normal.clone(), elevated.clone(), high.clone()],
        max_tokens: cost(&high) + cost(&elevated),
        deduplicate: false,
    };
    let packet = compile_context_with(&request, &CharDiv4Counter).unwrap();
    assert_eq!(packet.included_ids, ["high", "elevated"]);
    assert_eq!(packet.omitted_ids, ["normal"]);

    let request = ContextRequest {
        items: vec![normal, elevated.clone()],
        max_tokens: cost(&elevated),
        deduplicate: false,
    };
    let packet = compile_context_with(&request, &CharDiv4Counter).unwrap();
    assert_eq!(packet.included_ids, ["elevated"]);
    assert_eq!(packet.omitted_ids, ["normal"]);
}

#[test]
fn critical_still_fails_closed_with_elevated_evidence_present() {
    let elevated = item("elevated", "short", EvidencePriority::Elevated);
    let critical = item("critical", &"c".repeat(200), EvidencePriority::Critical);
    let budget = CharDiv4Counter.count(&render_item(&elevated, &elevated.content));
    let request = ContextRequest {
        items: vec![elevated, critical],
        max_tokens: budget,
        deduplicate: false,
    };
    assert!(matches!(
        compile_context_with(&request, &CharDiv4Counter),
        Err(ContextError::CriticalItemExceedsBudget { id, budget: b, .. })
            if id == "critical" && b == budget
    ));
}

